// Writes content/creativity/wordlist.js from the SCOWL word lists in the npm package
// wordlist-english (version 1.2.1). Development only; the package is not a dependency.
//
//   node tests/write-wordlist.mjs <path to the unpacked wordlist-english package>
//
// Lists used: english, british and american at SCOWL sizes 10, 20 and 35 (the common words),
// lower-case a to z only. The SCOWL copyright and permission notice is in
// content/creativity/SCOWL-COPYRIGHT.txt and is repeated in the generated file's header.

import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const dir = process.argv[2];
if (!dir) { console.error('usage: node tests/write-wordlist.mjs <wordlist-english directory>'); process.exit(1); }
const words = new Set();
for (const variety of ['english', 'british', 'american']) {
  for (const size of [10, 20, 35]) {
    for (const w of JSON.parse(readFileSync(join(dir, `${variety}-words-${size}.json`), 'utf8'))) {
      if (/^[a-z]+$/.test(w)) words.add(w);
    }
  }
}
const list = [...words].sort();
const header = `// English word list for the creativity tasks' "not a word" check (src/skills/creativity/text.js).
// GENERATED by tests/write-wordlist.mjs; do not edit by hand. ${list.length} words.
//
// Source: SCOWL (Spell Checker Oriented Word Lists), sizes 10, 20 and 35, English, British and
// American lists, as packaged in the npm package wordlist-english 1.2.1; lower-case a to z only.
// Copyright 2000-2016 by Kevin Atkinson. Permission to use, copy, modify, distribute and sell
// these word lists, the associated scripts, the output created from the scripts, and its
// documentation for any purpose is hereby granted without fee, provided that the above copyright
// notice appears in all copies and that both that copyright notice and this permission notice
// appear in supporting documentation. Kevin Atkinson makes no representations about the
// suitability of this array for any purpose. It is provided "as is" without express or implied
// warranty. The full notice, including the copyrights of the lists SCOWL draws on, is in
// content/creativity/SCOWL-COPYRIGHT.txt.
`;
writeFileSync(new URL('../content/creativity/wordlist.js', import.meta.url), `${header}\nexport const WORDS = '${list.join(' ')}';\n`);
console.log(`wrote ${list.length} words`);
